module min_toll (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] entrances [0:7],\n    input [7:0] exits [0:7],\n    output reg [15:0] result,\n    output reg done\n);\n\n    parameter N = 8;\n\n    // States\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] SORT_ENTRANCES = 3'd1;\n    localparam [2:0] SORT_EXITS = 3'd2;\n    localparam [2:0] DP_INIT = 3'd3;\n    localparam [2:0] DP_COMPUTE = 3'd4;\n    localparam [2:0] DONE_STATE = 3'd5;\n\n    reg [2:0] state, next_state;\n    reg [7:0] sorted_entrances [0:7];\n    reg [7:0] sorted_exits [0:7];\n    reg [15:0] dp [0:8];\n    reg [3:0] i;\n    reg [3:0] sort_i, sort_j;\n    reg [7:0] temp;\n    reg sort_complete;\n\n    // INF value\n    localparam [15:0] INF = 16'hFFFF;\n    integer k;\n\n    function [15:0] abs_diff;\n        input [7:0] a;\n        input [7:0] b;\n        begin\n            abs_diff = (a > b) ? (a - b) : (b - a);\n        end\n    endfunction\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 16'd0;\n            for (k = 0; k < 8; k = k + 1) begin\n                sorted_entrances[k] <= 8'd0;\n                sorted_exits[k] <= 8'd0;\n            end\n            i <= 4'd0;\n            sort_i <= 4'd0;\n            sort_j <= 4'd0;\n            temp <= 8'd0;\n            sort_complete <= 1'b0;\n            for (k = 0; k <= 8; k = k + 1) begin\n                dp[k] <= 16'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        for (k = 0; k < N; k = k + 1) begin\n                            sorted_entrances[k] <= entrances[k];\n                            sorted_exits[k] <= exits[k];\n                        end\n                        sort_i <= 4'd0;\n                        sort_j <= 4'd0;\n                        state <= SORT_ENTRANCES;\n                    end\n                end\n\n                SORT_ENTRANCES: begin\n                    if (sort_i < N - 1) begin\n                        if (sort_j < N - 1 - sort_i) begin\n                            if (sorted_entrances[sort_j] > sorted_entrances[sort_j + 1]) begin\n                                temp <= sorted_entrances[sort_j];\n                                sorted_entrances[sort_j] <= sorted_entrances[sort_j + 1];\n                                sorted_entrances[sort_j + 1] <= temp;\n                            end\n                            sort_j <= sort_j + 1;\n                        end else begin\n                            sort_j <= 4'd0;\n                            sort_i <= sort_i + 1;\n                        end\n                    end else begin\n                        sort_i <= 4'd0;\n                        sort_j <= 4'd0;\n                        state <= SORT_EXITS;\n                    end\n                end\n\n                SORT_EXITS: begin\n                    if (sort_i < N - 1) begin\n                        if (sort_j < N - 1 - sort_i) begin\n                            if (sorted_exits[sort_j] > sorted_exits[sort_j + 1]) begin\n                                temp <= sorted_exits[sort_j];\n                                sorted_exits[sort_j] <= sorted_exits[sort_j + 1];\n                                sorted_exits[sort_j + 1] <= temp;\n                            end\n                            sort_j <= sort_j + 1;\n                        end else begin\n                            sort_j <= 4'd0;\n                            sort_i <= sort_i + 1;\n                        end\n                    end else begin\n                        state <= DP_INIT;\n                    end\n                end\n\n                DP_INIT: begin\n                    dp[0] <= 16'd0;\n                    if (sorted_entrances[0] != sorted_exits[0])\n                        dp[1] <= abs_diff(sorted_entrances[0], sorted_exits[0]);\n                    else\n                        dp[1] <= INF;\n                    i <= 4'd1;\n                    state <= DP_COMPUTE;\n                end\n\n                DP_COMPUTE: begin\n                    if (i < N) begin\n                        reg [15:0] min_val;\n                        min_val = dp[i] + abs_diff(sorted_entrances[i], sorted_exits[i]);\n                        \n                        if (i >= 4'd1) begin\n                            reg [15:0] option2;\n                            option2 = dp[i-1] + abs_diff(sorted_entrances[i], sorted_exits[i-1]) + abs_diff(sorted_entrances[i-1], sorted_exits[i]);\n                            if (option2 < min_val) min_val = option2;\n                        end\n                        \n                        if (i >= 4'd2) begin\n                            reg [15:0] option3, option4;\n                            option3 = dp[i-2] + abs_diff(sorted_entrances[i], sorted_exits[i-2]) + abs_diff(sorted_entrances[i-1], sorted_exits[i]) + abs_diff(sorted_entrances[i-2], sorted_exits[i-1]);\n                            option4 = dp[i-2] + abs_diff(sorted_entrances[i], sorted_exits[i-1]) + abs_diff(sorted_entrances[i-1], sorted_exits[i-2]) + abs_diff(sorted_entrances[i-2], sorted_exits[i]);\n                            \n                            if (option3 < min_val) min_val = option3;\n                            if (option4 < min_val) min_val = option4;\n                        end\n                        \n                        dp[i+1] <= min_val;\n                        i <= i + 1;\n                    end else begin\n                        result <= dp[N];\n                        done <= 1'b1;\n                        state <= DONE_STATE;\n                    end\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b0;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule